def find_enclosure_fill(grid):
    """
    Find all enclosed regions formed by a boundary color and fill them.

    The rule is: find rectangular enclosures (regions bounded by a single non-background color)
    and fill the enclosed background color with 4.
    """
    if not grid or not grid[0]:
        return grid[:]

    H, W = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find the background color
    background = grid[0][0]

    # Find the boundary color (most common non-background? or second most common?)
    from collections import Counter
    all_colors = [c for row in grid for c in row]
    color_counts = Counter(all_colors)

    # There are typically 3 colors: background, boundary, fill
    # The background is grid[0][0]
    background = grid[0][0]

    # Find another non-background color that forms the enclosure
    for color, count in color_counts.most_common():
        if color != background and count > background:
            boundary_color = color
            break
    else:
        # If no second color found, boundary might be background itself
        boundary_color = background

    # Flood fill to find holes
    visited = [[False]*W for _ in range(H)]

    def flood_fill(start_r, start_c, fill_color):
        """Flood fill from start point, return all connected cells"""
        cells = []
        stack = [(start_r, start_c)]
        visited[start_r][start_c] = True

        while stack:
            r, c = stack.pop()
            cells.append((r, c))

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    if not visited[nr][nc]:
                        if result[nr][nc] == fill_color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

        return cells

    def is_border_color(r, c):
        return 0 <= r < H and 0 <= c < W and result[r][c] == boundary_color

    def is_empty(r, c):
        return 0 <= r < H and 0 <= c < W and result[r][c] != boundary_color

    def is_filled(r, c):
        return 0 <= r < H and 0 <= c < W and result[r][c] != background

    # Simpler approach: identify rectangular enclosures
    # Look for 2x2+ rectangular boundaries

    for top in range(H):
        for bot in range(top + 2, H):
            for left in range(W):
                for right in range(left + 2, W):
                    # Check if this forms a rectangular enclosure
